m["OnePit/Pit/V6nPitMerlin.cs"]=`using System;
using UnityEngine;

namespace Pitt.OnePit
{
    /// NB119/120: only the last, large step of a chapter is a timed economic wall.
    /// Invariants: Locked never decreases; only Tail expires; budget is frozen;
    /// this model has no wallet/upgrades reference. Reward is a delta, never replayed on restore.
    public sealed class V6nPitMerlin
    {
        [Serializable]
        public sealed class State
        {
            public bool Ready;
            public int Locked, Rewarded;
            public double Base, Tail, Remaining;
        }
        public State Data { get; private set; } = new State();
        public const double Ratio = 1.8, Weight = 6.04;
        public const float Window = 120f;
        public double Segment(int index) => Data.Base * Math.Pow(Ratio, Math.Max(0, Math.Min(2, index)));
        public double Total => Data.Base * Weight;
        public double Secured => Data.Locked == 0 ? 0 : Data.Locked == 1 ? Data.Base : Data.Locked == 2 ? Data.Base * 2.8 : Total;
        public double Fraction => Total > 0 ? Math.Min(1, (Secured + Data.Tail) / Total) : 0;
        public bool Complete => Data.Ready && Data.Locked == 3;
        public void Reset() => Data = new State();

        // expectedValue is the unchanged old goal valued at entry prices.
        // At the measured pre-wall rate R, segment II requires at least 1.44 R,
        // segment III at least 2.592 R. Price, colour, supply and actual paid turbo help.
        public void Begin(double expectedValue, double measuredRate, double oldFraction = 0)
        {
            if (Data.Ready) return;
            Data = new State { Ready = true, Base = Math.Max(0.01,
                Math.Max(expectedValue / Weight, measuredRate * Window * 0.8)) };
            double legacy = Total * Math.Max(0, Math.Min(1, oldFraction));
            while (Data.Locked < 3 && legacy >= Segment(Data.Locked))
            { legacy -= Segment(Data.Locked); Data.Locked++; }
            Data.Tail = Complete ? 0 : legacy;
            // Migrated checkpoints grant no retroactive bonus.
            Data.Rewarded = (1 << Data.Locked) - 1;
            Data.Remaining = Data.Tail > 0 ? Window : 0;
        }

        public bool Advance(double seconds)
        {
            if (!Data.Ready || Complete || Data.Remaining <= 0 || !(seconds > 0)) return false;
            Data.Remaining = Math.Max(0, Data.Remaining - seconds);
            if (Data.Remaining > 0) return false;
            Data.Tail = 0; // no write to Locked, Rewarded, Base, wallet or purchases
            return true;
        }

        /// One receipt cannot overshoot into a second attempt. Full receipt still stays in wallet.
        public double Credit(double paid)
        {
            if (!Data.Ready || Complete || !(paid > 0) || double.IsInfinity(paid)) return 0;
            if (Data.Remaining <= 0) Data.Remaining = Window;
            Data.Tail += paid;
            if (Data.Tail + 1e-9 < Segment(Data.Locked)) return 0;
            int index = Data.Locked;
            double reward = index < 2 && (Data.Rewarded & (1 << index)) == 0 ? Segment(index) * 0.01 : 0;
            Data.Rewarded |= 1 << index;
            Data.Locked++;
            Data.Tail = Data.Remaining = 0;
            return reward;
        }

        public State Capture() => new State { Ready = Data.Ready, Locked = Data.Locked,
            Rewarded = Data.Rewarded, Base = Data.Base, Tail = Data.Tail, Remaining = Data.Remaining };
        public void Restore(State s)
        {
            Reset();
            if (s == null || !s.Ready || !(s.Base > 0) || double.IsInfinity(s.Base)) return;
            int locked = Math.Max(0, Math.Min(3, s.Locked));
            Data = new State { Ready = true, Locked = locked, Base = s.Base,
                Rewarded = s.Rewarded | ((1 << locked) - 1) };
            if (locked == 3) return;
            Data.Remaining = double.IsNaN(s.Remaining) ? 0 : Math.Max(0, Math.Min(Window, s.Remaining));
            Data.Tail = Data.Remaining > 0 && !double.IsNaN(s.Tail)
                ? Math.Max(0, Math.Min(Segment(locked) * (1 - 1e-9), s.Tail)) : 0;
        }
    }
}
